\usepackage{chessboard}

% Start position with white pieces
\def\FEN{rnbk1nr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1}

\begin{document}
  \makebox[\chessboardSize][c]{
    \chessboard{\FEN}
  }
\end{document}
```

